close all
clear
clc

% Simulation
% Initial State
x = [pi/4 + 0.01; pi/4 + 0.01; 0; 0; 0; 0; 0; 0; 0; 0];

motor_speed = [0;0];           % carry motor integrator

dt = 0.001;
T  = 5;                        % simulate 5 seconds
N  = T/dt;

Xlog = zeros(10,N);

for k = 1:N

    % --- Compute control ---
    [u, motor_speed] = control_block(x, motor_speed);

    % --- Dynamics ---
    xdot = cube_dynamics(x, u);

    % --- Integrate ---
    x = x + dt * xdot;

    % --- Log ---
    Xlog(:,k) = x;
end

% Plot angle responses
t = (0:N-1)*dt;
plot(t, Xlog(1,:), t, Xlog(2,:))
legend('theta','phi')
xlabel('time (s)')
ylabel('angle (rad)')
title('Cube Angles vs Time')






