% Cube Controller Function
function [u, motor_speed] = control_block(x, motor_speed)

    % State extraction
    angleX = x(1);
    angleY = x(2);
    gyroZ  = x(6);
    gyroY  = x(7);

    motor_speed_X = motor_speed(1);
    motor_speed_Y = motor_speed(2);

    % Gains
    K1 = 160; K2 = 10.5; K3 = 0.03;

    % ---- Reference angles (your 45-degree target) ----
    theta_ref = deg2rad(45);
    phi_ref   = deg2rad(45);

    % ---- Compute controller outputs ----
    pwm_X = K1*(angleX - theta_ref) + K2*gyroZ + K3*motor_speed_X;
    pwm_Y = K1*(angleY - phi_ref)   + K2*gyroY + K3*motor_speed_Y;

    % Constrain to [-255, +255]
    pwm_X = max(min(pwm_X, 255), -255);
    pwm_Y = max(min(pwm_Y, 255), -255);

    % ---- Update motor speed integrators (same as Arduino) ----
    motor_speed_X = motor_speed_X + pwm_X;
    motor_speed_Y = motor_speed_Y + pwm_Y;

    motor_speed = [motor_speed_X; motor_speed_Y];

    % ---- XY → three-way motor allocation ----
    m1 = 0.5 * pwm_X - 0.75 * pwm_Y;
    m2 = 0.5 * pwm_X + 0.75 * pwm_Y;
    m3 = -pwm_X;

    % Constrain motors
    m1 = max(min(m1, 255), -255);
    m2 = max(min(m2, 255), -255);
    m3 = max(min(m3, 255), -255);

    % ---- Outputs (accelerations) ----
    qXDDt = m1;
    qYDDt = m2;
    qZDDt = m3;   % <- this is your "natural" Z-axis correction

    u = [qXDDt; qYDDt; qZDDt];
    u = u * 4; % Scale PWM to acceleration
end
